export function getEstadoCupo(disp: number, max: number, minimo: number): EstadoCupo {
  const ratio = max > 0 ? disp / max : 1;
  if (disp === 0) return 'agotado';
  if (disp <= minimo) return 'ultimos';
  if (ratio > 0.5) return 'disponible';
  return 'medio';
}

